SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE `deploy_execution`;
TRUNCATE TABLE `deploy_log`;
TRUNCATE TABLE `alarm`;
TRUNCATE TABLE `deploy`;

SET FOREIGN_KEY_CHECKS = 1;

-- 实例：部分环境已有成功版本，便于晋级与回滚演示
UPDATE `app_instance` SET `version` = NULL, `status` = 'OFFLINE';
UPDATE `app_instance` SET `version` = 'v2.2.0', `status` = 'ONLINE' WHERE `app_id` = 1 AND `env_code` = 'DEV';
UPDATE `app_instance` SET `version` = 'v2.2.0', `status` = 'ONLINE' WHERE `app_id` = 1 AND `env_code` = 'TEST';
UPDATE `app_instance` SET `version` = 'v2.1.0', `status` = 'ONLINE' WHERE `app_id` = 1 AND `env_code` = 'PROD';
UPDATE `app_instance` SET `version` = 'v2.0.8', `status` = 'ONLINE' WHERE `app_id` = 2 AND `env_code` = 'DEV';
UPDATE `app_instance` SET `version` = 'v2.0.8', `status` = 'ONLINE' WHERE `app_id` = 2 AND `env_code` = 'TEST';
UPDATE `app_instance` SET `version` = 'v1.9.4', `status` = 'ONLINE' WHERE `app_id` = 3 AND `env_code` = 'TEST';
UPDATE `app_instance` SET `version` = 'v0.9.1', `status` = 'DEPLOYING' WHERE `app_id` = 5 AND `env_code` = 'DEV';

